-- Table structure for table `notices`
CREATE TABLE `notices` (
  `notice_id` varchar(10) NOT NULL,
  `title` varchar(200) NOT NULL,
  `description` text NOT NULL,
  `notice_date` date NOT NULL,
  `created_by` varchar(10) NOT NULL,
  `status` enum('ACTIVE','INACTIVE') DEFAULT 'ACTIVE'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `notices` (`notice_id`, `title`, `description`, `notice_date`, `created_by`, `status`) VALUES
('NOT001', 'Level II Semester I Academic Timetable Published', 'The official Level II Semester 1 lecture and laboratory timetable has been finalized and uploaded for all ICT and TCS courses.', '2026-02-01', 'ADM001', 'ACTIVE'),
('NOT002', 'Submission of Medical Leave Certificates (7-Day Rule)', 'All undergraduates are reminded that medical leave certificates must be submitted to the Technical Officer within 7 calendar days of absence.', '2026-02-10', 'ADM001', 'ACTIVE'),
('NOT003', 'Continuous Assessment (CA) 40% Minimum Threshold', 'Undergraduates must obtain a minimum CA mark of 40% and 80% physical attendance to qualify for End Semester Examinations.', '2026-02-15', 'ADM001', 'ACTIVE'),
('NOT004', 'OOPP Project Practicum Guidelines and Deadlines', 'All practical project repositories must be pushed to GitHub with documentation before Sunday 11:59 PM.', '2026-02-20', 'ADM001', 'ACTIVE');

